// Chapter three: a timed dodge/counter encounter, followed by the birthday gate.
let bossHP=100,bossTime=0,bossPhase='warning',bossTarget=1,bossTimer=1.8,bossActive=false,bossWon=false,bossFlash=0,attackCooldown=0,shots=[],bossHits=0;
const runnerStart=start,runnerFrame=frame,runnerDraw=draw,runnerAct=act;
start=function(){bossHP=100;bossTime=0;bossPhase='warning';bossTarget=1;bossTimer=1.8;bossActive=bossWon=false;bossHits=0;shots=[];attackCooldown=bossFlash=0;runnerStart()};
act=function(){if(!playing||paused)return;if(mode!==2||bossWon){runnerAct();return}if(attackCooldown>0)return;attackCooldown=.45;shots.push({x:visualLane,t:0,hit:false});beep(580,.1);if(bossPhase==='exposed'){bossHP=Math.max(0,bossHP-20);bossFlash=.25;toast(bossHP>0?['Phản biện: chiếc răng này nên rời cuộc họp.','Tên là khôn. Chiến thuật thì chưa.','Vy 1 — răng khôn 0.'][Math.floor((100-bossHP)/20)%3]:'Răng khôn đã xin phép rời nhóm!',2);if(bossHP===0){bossWon=true;bossActive=false;objects=[];stopClip();$('chapterTitle').textContent='Boss đã rời nhóm. Đến giờ lên đồ!';$('action').textContent='Về đích ↑';toast('Đã tiễn một chiếc răng. Vẫn giữ nguyên phong độ.',5)}}else toast('Boss đang giơ khiên! Né vùng đỏ, đợi lúc nó choáng rồi phản công.',2)};
$('action').onclick=()=>act();
const counterAct=act;
act=function(){const hp=bossHP;counterAct();if(bossHP<hp&&!bossWon){bossPhase='recover';bossTimer=.7}};
frame=function(t){if(mode!==2){runnerFrame(t);return}if(!bossActive&&!bossWon){bossActive=true;bossTimer=2;objects=[];$('chapterTitle').textContent='BOSS: Răng Khôn — chọn sai ngày xuất hiện.';$('instruction').textContent='Né làn đỏ bằng ← → · Chạm / Space để phản công khi boss choáng';$('action').textContent='Phản công ✦';toast('Boss chặn cửa rạp! Né đòn rồi phản công lúc nó choáng.',4)}
const dt=last?Math.min((t-last)/1000,.04):0;last=t;if(!paused){elapsed+=dt;bossTime+=dt;visualLane+=(lane-visualLane)*Math.min(1,dt*13);rain=Math.max(0,rain-dt*.3);flood=Math.max(0,flood-dt*.5);bossFlash=Math.max(0,bossFlash-dt);attackCooldown=Math.max(0,attackCooldown-dt);invincible=Math.max(0,invincible-dt);shots.forEach(s=>s.t+=dt);shots=shots.filter(s=>s.t<.5);if(bossWon){distance=Math.min(1710,distance+dt*150);if(distance>=1710){finish();return}}else{bossTimer-=dt;if(bossTimer<=0){if(bossPhase==='warning'){bossPhase='slam';bossTimer=.4;if(lane===bossTarget){invincible=1;bossHits++;beep(130,.18);toast('Trúng sóng sưng má! Áo giáp sinh nhật đã đỡ giúp Vy.',2)}else{beep(700,.1);toast('Né đẹp! Boss đang choáng — phản công ngay!',2)}}else if(bossPhase==='slam'){bossPhase='exposed';bossTimer=2.4}else{bossPhase='warning';bossTimer=1.6;bossTarget=(bossTarget+1+Math.floor(Math.random()*2))%3}}}if(elapsed>toastUntil)$('bubble').hidden=true}
if(noiseGain)noiseGain.gain.value=sound&&!paused?rain*.055:0;draw();$('distance').textContent=Math.floor(distance).toLocaleString('vi-VN')+' m';$('progress').style.width=distance/1710*100+'%';$('threat').textContent=bossWon?'Đường tới sinh nhật đã mở':`BOSS RĂNG KHÔN · ${bossHP}/100`;$('action').disabled=paused||(!bossWon&&attackCooldown>0);raf=requestAnimationFrame(frame)};
draw=function(){runnerDraw();if(mode!==2)return;const w=canvas.clientWidth,h=canvas.clientHeight;if(!bossWon){if(bossPhase==='warning'||bossPhase==='slam'){const a=project(bossTarget-.48,.55,w,h),b=project(bossTarget+.48,.55,w,h),c=project(bossTarget+.48,0,w,h),d=project(bossTarget-.48,0,w,h);ctx.globalAlpha=bossPhase==='slam'?.6:.22+Math.sin(bossTime*12)*.1;poly([[a.x,a.y],[b.x,b.y],[c.x,c.y],[d.x,d.y]],'#ff6655');ctx.globalAlpha=1;text('NÉ LÀN ĐỎ',w/2,h*.38,12,'#ffb39f')}drawTooth(w/2,h*.50,Math.min(w/340,1.5));const barW=Math.min(250,w*.7);ctx.fillStyle='#101f2a';ctx.fillRect(w/2-barW/2,h*.14,barW,10);ctx.fillStyle=bossPhase==='exposed'?'#dfb77c':'#ce7564';ctx.fillRect(w/2-barW/2,h*.14,barW*bossHP/100,10);text(`RĂNG KHÔN · ${bossHP}/100`,w/2,h*.14-10,11);text(bossPhase==='exposed'?'ĐANG CHOÁNG · PHẢN CÔNG!':'CHUẨN BỊ NÉ ĐÒN',w/2,h*.60,12,bossPhase==='exposed'?'#f4d38b':'#e5b5a6')}
for(const s of shots){const p=project(s.x,.1+s.t*1.3,w,h);ctx.fillStyle='#ffe2a0';ctx.shadowColor='#f9b84b';ctx.shadowBlur=15;ctx.beginPath();ctx.arc(p.x,p.y-45,6*(1-s.t),0,7);ctx.fill();ctx.shadowBlur=0}};
function drawTooth(x,y,s){ctx.save();ctx.translate(x,y+Math.sin(bossTime*3)*4);ctx.scale(s,s);if(bossPhase==='slam')ctx.rotate(Math.sin(bossTime*40)*.08);ctx.shadowColor='#0006';ctx.shadowBlur=22;ctx.fillStyle='#132b38';ctx.beginPath();ctx.ellipse(0,50,65,13,0,0,7);ctx.fill();ctx.shadowBlur=0;const g=ctx.createLinearGradient(-50,-85,55,50);g.addColorStop(0,bossFlash>0?'#fff8c7':'#fff7e7');g.addColorStop(.55,'#e9e0ce');g.addColorStop(1,'#9faab0');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(0,-76);ctx.bezierCurveTo(-75,-110,-65,-20,-47,8);ctx.bezierCurveTo(-40,25,-43,58,-24,48);ctx.lineTo(-5,17);ctx.quadraticCurveTo(0,10,6,20);ctx.lineTo(25,49);ctx.bezierCurveTo(45,62,42,24,48,6);ctx.bezierCurveTo(72,-35,61,-111,0,-76);ctx.fill();ctx.strokeStyle='#777989';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-35,-50);ctx.lineTo(-13,-44);ctx.moveTo(13,-44);ctx.lineTo(35,-50);ctx.stroke();ctx.fillStyle='#263343';if(bossPhase==='exposed'){text('×',-22,-26,23,'#435563');text('×',22,-26,23,'#435563');text('✦',-50,-80,19,'#e3bd73');text('✦',52,-67,14,'#e3bd73')}else{ctx.beginPath();ctx.ellipse(-22,-32,5,7,0,0,7);ctx.ellipse(22,-32,5,7,0,0,7);ctx.fill()}ctx.fillStyle='#d9988d88';ctx.beginPath();ctx.ellipse(-36,-12,12,7,0,0,7);ctx.ellipse(36,-12,12,7,0,0,7);ctx.fill();ctx.strokeStyle='#65717c';ctx.beginPath();ctx.arc(0,-13,13,.1,3);ctx.stroke();if(bossPhase!=='exposed'){ctx.strokeStyle='#d5b479';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-25,78,0,7);ctx.stroke()}ctx.restore()}
// A more detailed, shaded sports character, seen from behind.
runner=function(x,y,s=1,chaser=false){ctx.save();ctx.translate(x,y);ctx.scale(s*1.12,s*1.12);const swing=mode===2&&!bossWon?0:Math.sin(elapsed*13),hair=chaser?'#202937':'#302731';ctx.lineCap='round';ctx.lineJoin='round';const leg=(side)=>{ctx.strokeStyle=chaser?'#243340':'#263745';ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(side*7,-27);ctx.quadraticCurveTo(side*12+swing*side*7,-10,side*11+swing*side*12,9);ctx.stroke();ctx.strokeStyle='#eee7d7';ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(side*11+swing*side*12,10);ctx.lineTo(side*18+swing*side*12,12);ctx.stroke()};leg(-1);leg(1);ctx.strokeStyle='#e4b69d';ctx.lineWidth=7;for(const side of [-1,1]){ctx.beginPath();ctx.moveTo(side*12,-59);ctx.quadraticCurveTo(side*20,-42+swing*side*8,side*16,-29+swing*side*12);ctx.stroke()}const g=ctx.createLinearGradient(-16,0,17,0);g.addColorStop(0,chaser?'#873d40':'#4a7980');g.addColorStop(.5,chaser?'#cf6d62':'#8cbab6');g.addColorStop(1,chaser?'#963f48':'#3f6974');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(-12,-65);ctx.quadraticCurveTo(0,-70,12,-65);ctx.lineTo(16,-45);ctx.lineTo(11,-26);ctx.quadraticCurveTo(0,-23,-11,-26);ctx.lineTo(-16,-45);ctx.closePath();ctx.fill();ctx.strokeStyle='#e4cba3';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,-61);ctx.lineTo(0,-31);ctx.stroke();ctx.fillStyle='#d8ac91';ctx.fillRect(-5,-75,10,11);ctx.beginPath();ctx.ellipse(0,-82,12,15,0,0,7);ctx.fill();ctx.fillStyle=hair;ctx.beginPath();ctx.ellipse(0,-87,14,16,0,0,7);ctx.fill();if(!chaser){ctx.beginPath();ctx.moveTo(6,-87);ctx.bezierCurveTo(29,-85,12+swing*6,-56,24+swing*8,-54);ctx.bezierCurveTo(4,-50,6,-71,6,-87);ctx.fill();ctx.fillStyle='#dfb77c';ctx.fillRect(8,-84,7,3);text('VY',0,-43,6,'#eaf0df')}ctx.restore()};
